InputArea.css:
/* ── The Composer as an Observatory Instrument ─────────────────
   The one surface that is always on screen, so it carries the theme. */
[data-component="InputArea"] {
  border: 1px solid rgba(155, 127, 212, 0.18) !important;
  border-radius: 16px !important;
  background:
    radial-gradient(120% 130% at 50% 120%, rgba(244, 162, 97, 0.07) 0%, transparent 58%),
