MessageList.css:
/* ── Message Cards ─────────────────────────────────────────────
   [data-component="BubbleMessage"] IS the card element (.card), and data-part
   carries the role: user / character / streaming. */
[data-component="BubbleMessage"] {
  border: 1px solid rgba(155, 127, 212, 0.16) !important;
  border-radius: 14px !important;
  background:
    linear-gradient(158deg, rgba(30, 23, 50, 0.92) 0%, rgba(19, 14, 33, 0.94) 58%, rgba(13, 9, 24, 0.96) 100%) !important;
  box-shadow: 0 10px 30px rgba(5, 3, 12, 0.45), inset 0 1px 0 rgba(255, 246, 229, 0.045) !important;
  transition: border-color 220ms ease, box-shadow 220ms ease, transform 220ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* a gold hairline along the top edge, like a chart rule */
[data-component="BubbleMessage"] {
  background-image:
    radial-gradient(140% 100% at 50% -30%, rgba(155, 127, 212, 0.13) 0%, transparent 55%),
    linear-gradient(158deg, rgba(30, 23, 50, 0.92) 0%, rgba(19, 14, 33, 0.94) 58%, rgba(13, 9, 24, 0.96) 100%) !important;
}

[data-component="BubbleMessage"]:hover {
  border-color: rgba(244, 162, 97, 0.26) !important;
  box-shadow: 0 14px 38px rgba(5, 3, 12, 0.52), 0 0 22px rgba(155, 127, 212, 0.10), inset 0 1px 0 rgba(255, 246, 229, 0.06) !important;
}

/* the character's voice gets the warmer frame; yours gets the colder one */
[data-component="BubbleMessage"][data-part="character"] {
  border-color: rgba(244, 162, 97, 0.22) !important;
}
[data-component="BubbleMessage"][data-part="character"]:hover {
  border-color: rgba(244, 162, 97, 0.38) !important;
}
[data-component="BubbleMessage"][data-part="user"] {
  border-color: rgba(155, 127, 212, 0.22) !important;
}

/* while Sola is writing, the card breathes a little */
[data-component="BubbleMessage"][data-part="streaming"] {
  border-color: rgba(244, 162, 97, 0.34) !important;
  box-shadow: 0 14px 40px rgba(5, 3, 12, 0.55), 0 0 30px rgba(244, 162, 97, 0.14) !important;
}

/* ── Avatars ───────────────────────────────────────────────────
   The two avatars in a bubble are told apart by alt text: the blurred
   background one is alt="", the header one carries the display name. */
[data-component="BubbleMessage"] img[alt]:not([alt=""]) {
  border-radius: 50% !important;
  border: 1px solid rgba(244, 162, 97, 0.35);
  box-shadow: 0 0 0 3px rgba(155, 127, 212, 0.10), 0 0 18px rgba(244, 162, 97, 0.14);
}

/* a star lander on the header seam */
[data-spindle-mount="message_header"]::after {
  content: '✦';
  color: rgba(244, 162, 97, 0.30);
  font-size: 9px;
  line-height: 1;
  margin-left: 8px;
  vertical-align: 1px;
}

/* ── Reading column ─────────────────────────────────────────────
   A little more air between turns; the sky does the rest. */
[data-component="MessageList"] {
  scroll-behavior: smooth;
}
[data-message-id] + [data-message-id] {
  margin-top: 4px;
}


/* A softly lit instrument plate, with the text still doing the talking. */
[data-component="BubbleMessage"] {
  border-color: rgba(157, 150, 215, .24) !important;
  border-radius: 13px !important;
