BubbleMessage.css:
/* ── Sola Zodiac — the turn rail ───────────────────────────────
   Markup comes from this pack's BubbleMessage TSX override, so these class
   names are ours to define. Nothing here touches a hashed module class.
   Lives in the same entry as the override: no markup, no need for the CSS. */
.sola-zodiac-turn {
  display: flex !important;
  align-items: stretch;
  gap: 10px;
}
.sola-zodiac-rail {
  flex: 0 0 34px;
  width: 34px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding: 11px 0 5px;
}
.sola-zodiac-sign {
  font-size: 17px;
  line-height: 1;
  color: #F4A261;
  text-shadow: 0 0 13px rgba(244, 162, 97, 0.38);
}
.sola-zodiac-turn[data-stance="user"] .sola-zodiac-sign {
  color: #9B7FD4;
  text-shadow: 0 0 13px rgba(155, 127, 212, 0.42);
}
.sola-zodiac-thread {
  flex: 1 1 auto;
  width: 1px;
  min-height: 10px;
  background: linear-gradient(180deg, rgba(155, 127, 212, 0.34) 0%, rgba(155, 127, 212, 0.05) 100%);
}
.sola-zodiac-ordinal {
  font-size: 10px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
  color: rgba(255, 246, 229, 0.34);
}
.sola-zodiac-mark {
  font-size: 11px;
  line-height: 1;
  color: rgba(244, 162, 97, 0.72);
}
.sola-zodiac-mark[data-pulse="yes"] {
  color: #F4A261;
  animation: sola-zodiac-pulse 2.4s ease-in-out infinite;
}
@keyframes sola-zodiac-pulse {
  0%, 100% { opacity: 0.42; text-shadow: none; }
  50%      { opacity: 1; text-shadow: 0 0 15px rgba(244, 162, 97, 0.55); }
}
@media (prefers-reduced-motion: reduce) {
  .sola-zodiac-mark[data-pulse="yes"] { animation: none; opacity: 1; }
}
.sola-zodiac-swipe {
  font-size: 10px;
  line-height: 1.4;
  font-variant-numeric: tabular-nums;
  color: #9B7FD4;
  border: 1px solid rgba(155, 127, 212, 0.32);
  border-radius: 9999px;
  padding: 1px 5px;
}
.sola-zodiac-plate {
  flex: 1 1 auto;
  min-width: 0;
}
@media (max-width: 600px) {
  .sola-zodiac-rail { flex: 0 0 24px; width: 24px; gap: 5px; }
  .sola-zodiac-sign { font-size: 14px; }
}


.sola-zodiac-sign { color: #E9C46A; font-variant-emoji: text; }
.sola-zodiac-turn[data-stance="user"] .sola-zodiac-sign { color: #ABB5FF; }
.sola-zodiac-thread {
  width: 1px;
  background: linear-gradient(180deg, rgba(133, 146, 230, .55), rgba(133, 146, 230, .08));
}
.sola-zodiac-ordinal { color: rgba(255, 246, 229, .62); }
.sola-zodiac-swipe { color: #D0CBFF; border-color: rgba(157, 150, 215, .48); }
@media (prefers-reduced-motion: reduce) {
  .sola-zodiac-mark[data-pulse="yes"] { animation: none !important; }
}

BubbleMessage.tsx:
export default function BubbleMessage({ message, swipes }) {
  const sign = message.index % 12 === 0 ? '♈'
    : message.index % 12 === 1 ? '♉'
    : message.index % 12 === 2 ? '♊'
    : message.index % 12 === 3 ? '♋'
    : message.index % 12 === 4 ? '♌'
    : message.index % 12 === 5 ? '♍'
    : message.index % 12 === 6 ? '♎'
    : message.index % 12 === 7 ? '♏'
    : message.index % 12 === 8 ? '♐'
    : message.index % 12 === 9 ? '♑'
    : message.index % 12 === 10 ? '♒'
    : '♓';
  const ordinal = message.index + 1;
  const stance = message.isUser ? 'user' : 'character';
  const flag = message.isContextAnchor ? 'anchor' : message.isHidden ? 'veiled' : 'clear';
  const swipeLabel = swipes.current + ' of ' + swipes.total;

  return (
    <div className="sola-zodiac-turn" data-sola-zodiac="turn" data-stance={stance} data-flag={flag} data-streaming={message.isStreaming ? 'yes' : 'no'}>
      <div className="sola-zodiac-rail" data-sola-zodiac="rail">
        <span className="sola-zodiac-sign" data-sola-zodiac="sign" title={message.displayName}>{sign}</span>
        <span className="sola-zodiac-thread" data-sola-zodiac="thread" />
        <span className="sola-zodiac-ordinal" data-sola-zodiac="ordinal">{ordinal}</span>
        {message.isContextAnchor ? <span className="sola-zodiac-mark" data-sola-zodiac="mark" title="Context anchor">⌖</span> : null}
        {message.isHidden ? <span className="sola-zodiac-mark" data-sola-zodiac="mark" title="Veiled from context">☾</span> : null}
        {message.isStreaming ? <span className="sola-zodiac-mark" data-sola-zodiac="mark" data-pulse="yes" title="Writing">✧</span> : null}
        {swipes.total > 1 ? <span className="sola-zodiac-swipe" data-sola-zodiac="swipe" title={swipeLabel}>{swipes.current}</span> : null}
      </div>
      <div className="sola-zodiac-plate" data-sola-zodiac="plate">
        <Original />
      </div>
    </div>
  );
}
